B.a4f=s(["CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)","CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)","CREATE TABLE branches (id INTEGER PRIMARY KEY, name TEXT NOT NULL)","CREATE TABLE categories (\n    id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('gelir','gider')), name TEXT NOT NULL,\n    system INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, UNIQUE (kind, name))","CREATE TABLE counterparties (\n    id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('musteri','tedarikci','banka','personel','diger')),\n    name TEXT NOT NULL, phone TEXT, email TEXT, tax_no TEXT, note TEXT, archived INTEGER NOT NULL DEFAULT 0,\n    created_at TEXT NOT NULL)","CREATE TABLE accounts (\n    id INTEGER PRIMARY KEY, branch_id INTEGER NOT NULL DEFAULT 1 REFERENCES branches(id),\n    kind TEXT NOT NULL CHECK (kind IN ('banka','nakit','kredi_karti','pos')),\n    name TEXT NOT NULL, bank_name TEXT, account_type TEXT,\n    currency TEXT NOT NULL CHECK (currency IN ('TRY','EUR','USD')),\n    credit_limit INTEGER, statement_day INTEGER, due_day INTEGER, payment_account_id INTEGER REFERENCES accounts(id),\n    last4 TEXT CHECK (last4 IS NULL OR (length(last4) = 4 AND last4 GLOB '[0-9][0-9][0-9][0-9]')),\n    note TEXT, archived INTEGER NOT NULL DEFAULT 0, sort INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL,\n    remind_enabled INTEGER NOT NULL DEFAULT 1, remind_offsets TEXT, remind_hour INTEGER, remind_cut INTEGER NOT NULL DEFAULT 1)","CREATE TABLE debit_cards (\n    id INTEGER PRIMARY KEY, name TEXT NOT NULL, bank_name TEXT, account_id INTEGER NOT NULL REFERENCES accounts(id),\n    last4 TEXT CHECK (last4 IS NULL OR (length(last4) = 4 AND last4 GLOB '[0-9][0-9][0-9][0-9]')),\n    status TEXT NOT NULL DEFAULT 'aktif' CHECK (status IN ('aktif','pasif')), created_at TEXT NOT NULL)","CREATE TABLE fx_rates (\n    id INTEGER PRIMARY KEY, day TEXT NOT NULL, currency TEXT NOT NULL CHECK (currency IN ('EUR','USD')),\n    rate_micro INTEGER NOT NULL CHECK (rate_micro > 0), source TEXT NOT NULL, created_at TEXT NOT NULL,\n    UNIQUE (day, currency))","CREATE TABLE txns (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, branch_id INTEGER NOT NULL DEFAULT 1, type TEXT NOT NULL, at TEXT NOT NULL,\n    description TEXT, category_id INTEGER REFERENCES categories(id), counterparty_id INTEGER REFERENCES counterparties(id),\n    pnl_amount INTEGER NOT NULL DEFAULT 0, pnl_currency TEXT NOT NULL DEFAULT 'TRY',\n    card_id INTEGER REFERENCES debit_cards(id), installments INTEGER NOT NULL DEFAULT 1,\n    ref_type TEXT, ref_id INTEGER, reversal_of INTEGER REFERENCES txns(id),\n    status TEXT NOT NULL DEFAULT 'aktif' CHECK (status IN ('aktif','iptal')),\n    fx_rate_micro INTEGER, fx_source TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL)","CREATE INDEX ix_txns_at ON txns(at)","CREATE INDEX ix_txns_type ON txns(type, at)","CREATE INDEX ix_txns_ref ON txns(ref_type, ref_id)","CREATE TABLE postings (\n    id INTEGER PRIMARY KEY, txn_id INTEGER NOT NULL REFERENCES txns(id), account_id INTEGER NOT NULL REFERENCES accounts(id),\n    amount INTEGER NOT NULL CHECK (amount <> 0), currency TEXT NOT NULL)","CREATE INDEX ix_postings_account ON postings(account_id, txn_id)","CREATE INDEX ix_postings_txn ON postings(txn_id)","CREATE TABLE documents (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, kind TEXT NOT NULL CHECK (kind IN ('cek','senet')),\n    direction TEXT NOT NULL CHECK (direction IN ('alinan','verilen')), number TEXT NOT NULL,\n    amount INTEGER NOT NULL CHECK (amount > 0), currency TEXT NOT NULL, issue_date TEXT NOT NULL, due_date TEXT NOT NULL,\n    bank_name TEXT, counterparty_id INTEGER REFERENCES counterparties(id), account_id INTEGER REFERENCES accounts(id),\n    debt_id INTEGER REFERENCES debts(id), category_id INTEGER REFERENCES categories(id), note TEXT, attachment TEXT,\n    status TEXT NOT NULL CHECK (status IN ('bekliyor','odendi','tahsil_edildi','iade_edildi','karsiliksiz','iptal')),\n    created_at TEXT NOT NULL, updated_at TEXT NOT NULL,\n    remind_enabled INTEGER NOT NULL DEFAULT 1, remind_offsets TEXT, remind_hour INTEGER)","CREATE INDEX ix_documents_due ON documents(status, due_date)","CREATE TABLE document_events (\n    id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES documents(id), at TEXT NOT NULL,\n    from_status TEXT, to_status TEXT NOT NULL, txn_id INTEGER REFERENCES txns(id), note TEXT)","CREATE TABLE debts (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, direction TEXT NOT NULL CHECK (direction IN ('borc','alacak')),\n    kind TEXT NOT NULL CHECK (kind IN ('tedarikci','musteri','kredi','fatura','maas','diger')),\n    counterparty_id INTEGER REFERENCES counterparties(id), title TEXT NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0),\n    currency TEXT NOT NULL, issue_date TEXT NOT NULL, due_date TEXT, category_id INTEGER REFERENCES categories(id),\n    installment_no INTEGER, installment_count INTEGER, group_uid TEXT, note TEXT,\n    status TEXT NOT NULL DEFAULT 'aktif' CHECK (status IN ('aktif','iptal')), source_type TEXT, source_id INTEGER,\n    created_at TEXT NOT NULL, remind_enabled INTEGER NOT NULL DEFAULT 1, remind_offsets TEXT, remind_hour INTEGER)","CREATE INDEX ix_debts_due ON debts(status, due_date)","CREATE TABLE debt_payments (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, debt_id INTEGER NOT NULL REFERENCES debts(id), txn_id INTEGER REFERENCES txns(id),\n    amount INTEGER NOT NULL CHECK (amount > 0), at TEXT NOT NULL, note TEXT,\n    status TEXT NOT NULL DEFAULT 'aktif' CHECK (status IN ('aktif','iptal')))","CREATE INDEX ix_debt_payments ON debt_payments(debt_id)","CREATE TABLE products (\n    id INTEGER PRIMARY KEY, name TEXT NOT NULL, barcode TEXT UNIQUE, category TEXT, unit TEXT NOT NULL DEFAULT 'adet',\n    cost INTEGER NOT NULL DEFAULT 0, price INTEGER NOT NULL DEFAULT 0, stock_qty INTEGER NOT NULL DEFAULT 0,\n    stock_value INTEGER NOT NULL DEFAULT 0, critical_level INTEGER NOT NULL DEFAULT 0,\n    supplier_id INTEGER REFERENCES counterparties(id), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL)","CREATE TABLE stock_moves (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, product_id INTEGER NOT NULL REFERENCES products(id), at TEXT NOT NULL,\n    qty INTEGER NOT NULL, value INTEGER NOT NULL, kind TEXT NOT NULL, ref_type TEXT, ref_id INTEGER, note TEXT,\n    created_at TEXT NOT NULL)","CREATE INDEX ix_stock_moves ON stock_moves(product_id, at)","CREATE TABLE staff (\n    id INTEGER PRIMARY KEY, name TEXT NOT NULL, title TEXT, phone TEXT, start_date TEXT, end_date TEXT,\n    salary INTEGER NOT NULL DEFAULT 0, shift_start TEXT, shift_end TEXT,\n    status TEXT NOT NULL DEFAULT 'aktif' CHECK (status IN ('aktif','pasif')), note TEXT, created_at TEXT NOT NULL,\n    remind_enabled INTEGER NOT NULL DEFAULT 1, remind_offsets TEXT, remind_hour INTEGER)","CREATE TABLE sales (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, no TEXT NOT NULL UNIQUE, at TEXT NOT NULL,\n    mode TEXT NOT NULL CHECK (mode IN ('hizli','urun')), gross INTEGER NOT NULL, discount INTEGER NOT NULL DEFAULT 0,\n    net INTEGER NOT NULL, payment TEXT NOT NULL CHECK (payment IN ('nakit','kart','havale','veresiye')),\n    account_id INTEGER REFERENCES accounts(id), counterparty_id INTEGER REFERENCES counterparties(id),\n    staff_id INTEGER REFERENCES staff(id), cogs INTEGER NOT NULL DEFAULT 0, cogs_estimated INTEGER NOT NULL DEFAULT 0,\n    txn_id INTEGER REFERENCES txns(id), debt_id INTEGER REFERENCES debts(id), note TEXT,\n    status TEXT NOT NULL DEFAULT 'aktif' CHECK (status IN ('aktif','iptal')), created_at TEXT NOT NULL)","CREATE INDEX ix_sales_at ON sales(at)","CREATE TABLE sale_items (\n    id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id),\n    name TEXT NOT NULL, qty INTEGER NOT NULL, unit_price INTEGER NOT NULL, line_total INTEGER NOT NULL,\n    net_total INTEGER NOT NULL, cost_total INTEGER NOT NULL, returned_qty INTEGER NOT NULL DEFAULT 0)","CREATE TABLE sale_returns (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, sale_id INTEGER NOT NULL REFERENCES sales(id), at TEXT NOT NULL,\n    amount INTEGER NOT NULL, cogs INTEGER NOT NULL, txn_id INTEGER REFERENCES txns(id), reason TEXT)","CREATE TABLE cash_sessions (\n    id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), day TEXT NOT NULL, opened_at TEXT NOT NULL,\n    opening INTEGER NOT NULL, system_at_open INTEGER NOT NULL, from_posting_id INTEGER NOT NULL, to_posting_id INTEGER,\n    closed_at TEXT, expected INTEGER, counted INTEGER, diff INTEGER, note TEXT)","CREATE TABLE purchases (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, no TEXT NOT NULL UNIQUE, supplier_id INTEGER NOT NULL REFERENCES counterparties(id),\n    at TEXT NOT NULL, invoice_no TEXT, total INTEGER NOT NULL, due_date TEXT, debt_id INTEGER REFERENCES debts(id),\n    status TEXT NOT NULL DEFAULT 'aktif', note TEXT, created_at TEXT NOT NULL)","CREATE TABLE purchase_items (\n    id INTEGER PRIMARY KEY, purchase_id INTEGER NOT NULL REFERENCES purchases(id), product_id INTEGER NOT NULL REFERENCES products(id),\n    qty INTEGER NOT NULL, unit_cost INTEGER NOT NULL, line_total INTEGER NOT NULL)","CREATE TABLE attendance (\n    id INTEGER PRIMARY KEY, staff_id INTEGER NOT NULL REFERENCES staff(id), day TEXT NOT NULL,\n    status TEXT NOT NULL CHECK (status IN ('calisti','izinli','raporlu','devamsiz')), check_in TEXT, check_out TEXT,\n    worked_min INTEGER NOT NULL DEFAULT 0, overtime_min INTEGER NOT NULL DEFAULT 0, note TEXT, UNIQUE (staff_id, day))","CREATE TABLE payroll_items (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, staff_id INTEGER NOT NULL REFERENCES staff(id), period TEXT NOT NULL,\n    kind TEXT NOT NULL CHECK (kind IN ('prim','kesinti')), amount INTEGER NOT NULL CHECK (amount > 0), note TEXT,\n    status TEXT NOT NULL DEFAULT 'aktif', created_at TEXT NOT NULL)","CREATE TABLE salary_moves (\n    id INTEGER PRIMARY KEY, uid TEXT UNIQUE, staff_id INTEGER NOT NULL REFERENCES staff(id), period TEXT NOT NULL,\n    kind TEXT NOT NULL CHECK (kind IN ('avans','maas')), amount INTEGER NOT NULL CHECK (amount > 0),\n    txn_id INTEGER REFERENCES txns(id), at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'aktif')","CREATE TABLE counters (name TEXT PRIMARY KEY, value INTEGER NOT NULL)","CREATE TABLE audit_log (\n    id INTEGER PRIMARY KEY, at TEXT NOT NULL, action TEXT NOT NULL, entity TEXT, entity_id INTEGER, summary TEXT, detail TEXT)","CREATE INDEX ix_audit_at ON audit_log(at)"],t.s)
